<?php
function campaignContent(string $provider,string $key): array {
 $data=[
 'general'=>['בוחרים את החופשה הבאה','כל נסיעה טובה מתחילה בכיוון: חופשה בארץ, מלון בעיר חדשה או טיסה לחו״ל. בחרו תאריכים והרכב נוסעים ובדקו את האפשרויות באתר הספק.',['הגדירו תקציב כולל לטיסה, ללינה ולהוצאות הנלוות.','השוו כמה תאריכים סמוכים אם יש לכם גמישות.','בדקו את תנאי ההזמנה והשירות לפני שמאשרים.'],'coast.jpg'],
 'hotels'=>['מוצאים מלון שמתאים לחופשה','חופשה עירונית, חוף או בסיס לטיולי יום — בחרו מלון לפי מיקום וסוג האירוח שאתם מחפשים. באתר הספק תוכלו לחפש לפי יעד ותאריכים.',['בדקו מרחקים מתחבורה ציבורית וממוקדי הביקור.','השוו את סוג החדר, הרכב האורחים והארוחות הכלולות.','בדקו מסים מקומיים ותנאי ביטול של סוג החדר שבחרתם.'],'prague.jpg'],
 'packages'=>['טיסה ומלון. חופשה אחת שמתאימה לכם','חבילות נופש מרכזות את בחירת הטיסה והמלון. המשיכו לחבילות של אשת טורס ובדקו את היעד, מועדי הטיסה ורמת האירוח שמתאימים לכם.',['ודאו מה כלול בחבילה: טיסה, מלון, כבודה והעברות.','בדקו שעות נחיתה והמראה מול זמני הכניסה למלון.','השוו מחיר סופי לאותו הרכב נוסעים ומספר לילות.'],'coast.jpg'],
 'israel'=>['קצת חופש, קרוב לבית','ים, עיר או נוף פתוח — נופש בארץ מתחיל בבחירת האזור וסגנון האירוח. המשיכו למלונות ולחופשות בישראל באתר הספק.',['בחרו אזור לפי משך החופשה וזמן הנסיעה.','בדקו בסיס אירוח, חניה והתאמת החדר להרכב שלכם.','בררו שעות כניסה ויציאה ותנאי שינוי או ביטול.'],'coast.jpg'],
 'flights'=>['הטיול הבא מתחיל בטיסה הנכונה','בחרו יעד ותאריכים והמשיכו לחיפוש טיסות אצל הספק. כדאי להשוות גם את זמני הטיסה והכבודה, לצד מחיר הכרטיס.',['השוו טיסה ישירה מול זמן המסע הכולל בקונקשן.','בדקו כבודה, הושבה ועלויות שינוי בכרטיס הספציפי.','ודאו התאמה בין שמות הנוסעים למסמכי הנסיעה.'],'prague.jpg'],
 'organized'=>['מגלים עולם עם מסלול מתוכנן','טיול מאורגן מחבר בין המסלול, הלינה וההדרכה. המשיכו לטיולים המאורגנים של אשת טורס ובחרו יעד וקצב שמתאימים לכם.',['קראו את מסלול הטיול לפי ימים, כולל זמני נסיעה.','בדקו אילו כניסות, ארוחות וטיפים כלולים במחיר.','בררו את דרגת הקושי, שפת ההדרכה ותנאי היציאה.'],'alps.jpg'],
 'eilat'=>['זמן לחופשה באילת','בריכה, ים וזמן לעצמכם. המשיכו לעמוד המלונות באילת של אשת טורס ובדקו אפשרויות לפי התאריכים והרכב הנוסעים שלכם.',['בחרו מיקום לפי החופים והפעילויות שתרצו לשלב.','בדקו חדר משפחתי, ארוחות והגבלות גיל במתקנים.','השוו את עלות ההגעה והחניה כחלק מתקציב החופשה.'],'coast.jpg'],
 'north'=>['לוקחים הפסקה בצפון','שינוי אווירה ומקום לנוח בין טיולים. המשיכו לעמוד המלונות בצפון של אשת טורס ובחרו אזור ובסיס אירוח שמתאימים לכם.',['בדקו את מיקום המלון ביחס למסלול שתכננתם.','ודאו אילו מתקנים ושירותים פעילים במועד הביקור.','בדקו הנחיות עדכניות ותנאי ביטול לפני היציאה.'],'alps.jpg'],
 'flight-hotel'=>['מרכיבים טיסה ומלון בדרך שלכם','בחרו טיסה ומלון לפי ההעדפות שלכם בעמוד טיסה ומלון של אשת טורס. התאימו את המיקום, השעות והתקציב לחופשה שאתם מתכננים.',['השוו את העלות המשולבת מול הזמנה נפרדת.','בדקו האם תנאי השינוי והביטול שונים בין הטיסה למלון.','התאימו את מספר לילות המלון לשעות ההגעה והחזרה.'],'prague.jpg'],
 'europe'=>['החופשה באירופה מתחילה כאן','חופשה קצרה בעיר, ביקור משפחתי או נקודת התחלה למסלול ארוך. המשיכו לעמוד הטיסות של וואלה טורס ובחרו יעד ותאריכים באירופה.',['בדקו באיזה שדה תעופה נוחתים ומה עלות ההגעה לעיר.','השוו מחיר כרטיס עם אותה כמות כבודה.','גמישות של יום או יומיים עשויה להרחיב את אפשרויות החיפוש.'],'prague.jpg'],
 'usa'=>['מתכננים את הטיסה לארצות הברית','מסע ארוך כדאי לתכנן סביב זמני הטיסה, עצירות הביניים ויעד ההגעה. המשיכו לעמוד הטיסות לארה״ב של וואלה טורס לבדיקת האפשרויות.',['השוו משך מסע כולל וזמן מעבר בין טיסות.','בדקו תנאי כבודה והאם כל המקטעים באותה הזמנה.','בדקו מראש מסמכי כניסה ודרישות מעבר במקורות הרשמיים.'],'prague.jpg'],
 'long-haul'=>['מרחיקים קצת. מגלים הרבה','מתכננים יעד רחוק? התחילו בבחירת טיסה שמתאימה למסלול ולמשך החופשה. המשיכו לעמוד הטיסות ליעדים רחוקים של וואלה טורס.',['בדקו עצירות ביניים, החלפת שדות תעופה ומשך המסע.','תכננו זמן התאוששות אחרי הטיסה ביום ההגעה.','בררו תנאי כרטיס, כבודה ודרישות כניסה לפני התשלום.'],'alps.jpg'],
 'family'=>['חופשה משפחתית שמתאימה לכולם','זמן ביחד מתחיל בבחירות הנכונות למשפחה שלכם. המשיכו לחבילות הנופש המשפחתיות של וואלה טורס ובדקו יעדים, מלונות ותאריכים.',['הזינו גילאים מדויקים של הילדים לקבלת הרכב מתאים.','בדקו סידורי שינה, ארוחות ומתקנים לפי גיל.','השוו זמני טיסה והעברות כדי לשמור על יום הגעה נוח.'],'coast.jpg'],
 'sports'=>['הופכים את המשחק לחוויה שלמה','לראות את האירוע מקרוב ולשלב ביקור בעיר. המשיכו לחבילות הספורט של וואלה טורס ובדקו את האירוע ואת רכיבי החבילה.',['ודאו מה כלול: כרטיס לאירוע, טיסה, מלון והעברות.','בדקו קטגוריית מושבים ואופן קבלת הכרטיסים.','בררו מה קורה אם מועד האירוע או מיקומו משתנים.'],'prague.jpg']
 ];
 if($key==='international')$key='flights';if($key==='deals')$key='general';return $data[$key]??$data['general'];
}
function verifiedDestination(string $provider,string $key): string {
 $paths=['eshet'=>['general'=>'/','hotels'=>'/hotels/','packages'=>'/deals/','israel'=>'/domestichotels/','flights'=>'/flights/','organized'=>'/organized/','eilat'=>'/domestichotels/eilat/','deals'=>'/','north'=>'/domestichotels/north/','flight-hotel'=>'/deals/flight-hotel/','international'=>'/flights/'],'walla'=>['general'=>'/','europe'=>'/flights/promo.aspx','usa'=>'/flights/promo.aspx?id=usa','long-haul'=>'/flights/promo.aspx?id=longdest','family'=>'/packages/family.aspx','sports'=>'/sports/','israel'=>'/israel/','hotels'=>'/hotels/']];
 return ($provider==='eshet'?'https://www.eshet.com':'https://www.wallatours.co.il').$paths[$provider][$key];
}
